def footer(c,d):
 w,h=d.pagesize;c.setFillColor(g.BLUE);c.rect(0,h-37,w,37,fill=1,stroke=0);c.setFillColor(g.NAVY);c.setFont('ArialBold',8);c.drawString(44,h-23,'PAPER ADVENTURE / CELEBRATION HOME');c.setFont('Arial',8);c.drawString(44,28,f'H01 {d.role} / v0.4 / {d.paper}');c.drawRightString(w-44,28,f'Page {d.page}');c.setStrokeColor(g.LINE);c.line(44,42,w-44,42)

def main():
 g.validate_logic();items=[]
 for paper,size in [('A4',g.A4),('Letter',g.letter)]:
  for role,builder in [('player',player),('guide',guide)]:
   pages=builder(size[0]-88);path=OUT/f'celebration-home-{role}-v0.4-{paper}.pdf'
   doc=SimpleDocTemplate(str(path),pagesize=size,leftMargin=44,rightMargin=44,topMargin=60,bottomMargin=55,title=f'Celebration Home {role} v0.4',author='Paper Adventure');doc.role=role;doc.paper=paper
   flow=[]
   for i,content in enumerate(pages):
    if i:flow.append(PageBreak())
    flow.extend(content)
   doc.build(flow,onFirstPage=footer,onLaterPages=footer)
   count=len(PdfReader(path).pages);assert count==(10 if role=="player" else 12),(path,count)
   items.append(dict(path=path.relative_to(ROOT).as_posix(),paper=paper,role=role,pages=count,bytes=path.stat().st_size,sha256=hashlib.sha256(path.read_bytes()).hexdigest(),r2Key=f'free/celebration/home/v0.4/{paper}/{role}.pdf'))
 (OUT/'celebration-home-v0.4-manifest.json').write_text(json.dumps(dict(version='v0.4',items=items),indent=2)+'\n')
 print('Generated four v0.4 PDFs: Player 10 pages, Guide 12 pages in each paper size.')

if __name__=='__main__':main()

